import{_ as o,l as s,o as e,c as n,v as i,p as l,x as r,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Grace hash join","description":"","frontmatter":{"title":"Grace hash join","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/grace-hash-join.md","filePath":"cs/grace-hash-join.md","lastUpdated":1789023840000}'),p={name:"cs/grace-hash-join.md"};function _(E,a,u,f,m,b){const t=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="grace-hash-join" tabindex="-1">Grace hash join <a class="header-anchor" href="#grace-hash-join" aria-label="Permalink to &quot;Grace hash join&quot;">​</a></h1><div class="epigraph"><p>内存装不下 build 侧时，两边按连接键划分成对等分区，分区对分别做内存哈希；递归直到能放下。</p><footer>—— 据 Kitsuregawa et al. GRACE；DeWitt et al. 混合哈希；Blasgen and Eswaran；主干哈希连接的溢盘补全</footer></div><p><a href="/cs/hash-aggregation">上一课</a>对单输入分区。本课不更新组状态。缺口是等值连接在内存不够时：主干 <a href="/cs/nlj-hash-join">NLJ 与哈希</a> 点名 Grace 式分区。进阶把算法钉死，并行 shuffle 后课再加网络。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内存哈希：小侧 build，大侧 probe，一次扫描。build 超过工作内存：简单做法失败。Grace：用同一哈希函数的高位把 R 与 S 划成 \\(P\\) 个桶文件，保证 \\(R_i\\) 只可能连 \\(S_i\\)。然后对每个 \\(i\\)，把较小的一侧读入内存哈希，扫另一侧。若某分区仍太大，递归再划分。</p><p>混合哈希：第一分区常驻内存，其余落盘，减少 I/O。缺口是倾斜：一键对应极多行，分区无法切开该键——需要特殊处理（独立该键、或改 NLJ）。</p><p><span class="marginnote">Kitsuregawa, Tanaka, Moto-oka 的 GRACE 数据库机。DeWitt 等混合哈希。选择 build 侧仍靠估计；估错会把大侧当 build，分区文件爆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>划分遍：顺序扫两输入，写 \\(P\\) 对文件。处理遍：对 \\(i=1..P\\) 做内存连接。I/O：约两输入各读两次、写一次（划分写、处理读），常数优于朴素反复扫内表。\\(P\\) 选使期望分区适合内存。</p><p>位图过滤、布隆：probe 前丢弃必不命中行，后课 LSM 读放大也会用布隆，思想同源，结构不同。</p>',10)),(e(),l(d,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22R%22%5D%20--%3E%20P%5B%22%E6%8C%89%E9%94%AE%E5%88%92%E5%88%86%E6%88%90%20R_i%22%5D%0A%20%20S%5B%22S%22%5D%20--%3E%20Q%5B%22%E6%8C%89%E9%94%AE%E5%88%92%E5%88%86%E6%88%90%20S_i%22%5D%0A%20%20P%20--%3E%20JOIN%5B%22R_i%20%E4%B8%8E%20S_i%20%E5%86%85%E5%AD%98%E5%93%88%E5%B8%8C%22%5D%0A%20%20Q%20--%3E%20JOIN%0A%20%20JOIN%20--%3E%20REC%5B%22%E5%88%86%E5%8C%BA%E4%BB%8D%E5%A4%A7%E5%88%99%E9%80%92%E5%BD%92%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>迭代器：划分是阻塞的（先写完文件）。向量化按批算哈希、写页。编译内联哈希函数。WAL 不记录临时划分文件；崩溃则查询失败重来，不是恢复连接中途。</p><p>外连接：分区仍按键，未匹配行在处理遍按外连接规则吐 NULL——逻辑课已钉，执行器实现分支。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲跨节点的 exchange 与网络 shuffle——下一课并行。单机多核可用同一划分思想在内存队列上做，仍叫分区哈希。</p><p>后课默认：等值连接内存不够走 Grace/hybrid；倾斜键单独处理。并行查询把划分换成跨线程/跨节点的 exchange。</p><p>Grace 的正确性来自「同键同分区」；性能来自各分区独立且期望能放下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Grace 把两输入划成对等分区再分别哈希。</li><li>混合哈希保留一个内存分区；倾斜键破划分假设。</li><li>并行查询与 exchange 下一课：把分区送到多个工人。</li><li>出处：Kitsuregawa et al.；DeWitt 等；Ramakrishnan and Gehrke。</li></ul>',9))])}const P=o(p,[["render",_]]);export{A as __pageData,P as default};
